//! 剪贴板：只读文本，认「隐蔽 / 瞬时」标记，识别自己写入的那一次。

use objc2_app_kit::{NSPasteboard, NSPasteboardTypeString};
use objc2_foundation::NSString;

/// 密码管理器与系统在放敏感内容时打的标记（nspasteboard.org 约定），见到任何一个都不读。
const SECRET_TYPES: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "de.petermaurer.TransientPasteboardType",
];

/// 一次新复制。
pub struct Copied {
    pub text: String,

    /// 带了隐蔽 / 瞬时标记。
    pub concealed: bool,
}

pub struct ClipboardWatch {
    /// 上次看到的 changeCount。
    seen: isize,

    /// 自己写入剪贴板后的 changeCount，不当成用户复制。
    own: Option<isize>,
}

impl ClipboardWatch {
    /// 以当前剪贴板为起点：启动前已经复制的内容不处理。
    pub fn new() -> Self {
        Self {
            seen: NSPasteboard::generalPasteboard().changeCount(),
            own: None,
        }
    }

    /// 重新以当前为起点，激活输入法时调：之前复制的东西不追溯。
    pub fn reset(&mut self) {
        self.seen = NSPasteboard::generalPasteboard().changeCount();
    }

    /// 有新复制就返回它的文本；没变化或不是文本返回 `None`。
    pub fn poll(&mut self) -> Option<Copied> {
        let pasteboard = NSPasteboard::generalPasteboard();
        let count = pasteboard.changeCount();
        if count == self.seen {
            return None;
        }
        self.seen = count;
        if self.own == Some(count) {
            return None;
        }
        let concealed = pasteboard.types().is_some_and(|types| {
            types
                .iter()
                .any(|kind| SECRET_TYPES.contains(&kind.to_string().as_str()))
        });
        if concealed {
            // 隐蔽内容连文本都不读
            return Some(Copied {
                text: String::new(),
                concealed: true,
            });
        }
        // SAFETY: 只读 AppKit 导出的类型名常量
        let text = unsafe { pasteboard.stringForType(NSPasteboardTypeString) }?.to_string();
        Some(Copied {
            text,
            concealed: false,
        })
    }
}

/// 现在剪贴板里的文本，不管是不是新复制的；带隐蔽标记或不是文本返回 `None`。
pub fn read_now() -> Option<String> {
    let pasteboard = NSPasteboard::generalPasteboard();
    let concealed = pasteboard.types().is_some_and(|types| {
        types
            .iter()
            .any(|kind| SECRET_TYPES.contains(&kind.to_string().as_str()))
    });
    if concealed {
        return None;
    }
    // SAFETY: 只读 AppKit 导出的类型名常量
    unsafe { pasteboard.stringForType(NSPasteboardTypeString) }.map(|text| text.to_string())
}

/// 把文本写进剪贴板，并返回写入后的 changeCount，供 [`ClipboardWatch`] 认出这是自己写的。
pub fn write(text: &str) -> isize {
    let pasteboard = NSPasteboard::generalPasteboard();
    pasteboard.clearContents();
    // SAFETY: 只读 AppKit 导出的类型名常量
    unsafe {
        pasteboard.setString_forType(&NSString::from_str(text), NSPasteboardTypeString);
    }
    pasteboard.changeCount()
}

impl ClipboardWatch {
    /// 记下自己写入的那一次。
    pub fn mark_own(&mut self, count: isize) {
        self.own = Some(count);
        self.seen = count;
    }
}
